 '<div class="v69-th">'+PH.map(function(p,i){return '<button type="button" data-i="'+i+'" aria-label="Voir la photo '+(i+1)+'"><img src="'+p.s+'" alt=""></button>'}).join('')+'</div>'+
 '<div class="v69-loc"><i><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 5.500-8 11-8 11S4 15.500 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.600"/></svg></i><div><b>Collège FOHOUNDI Garango</b><small>Bouaflé · Lieu du Camp</small></div><a href="https://www.google.com/maps/search/?api=1&query=Coll%C3%A8ge+FOHOUNDI+Garango+Boua%C3%A9fl%C3%A9" target="_blank" rel="noopener">Itinéraire</a></div>';
 var tr=g.querySelector('.v69-tr'),th=g.querySelectorAll('.v69-th button'),idx=0,raf=0;
